// CommitMsg is called by the git commit-msg hook after the user edits the message.
// If the message contains only our trailer (no actual user content), strip it
// so git will abort the commit due to empty message.

func (s *ManualCommitStrategy) CommitMsg(ctx context.Context, commitMsgFile string) error { //nolint:unparam // error return is part of the hook contract; callers check it
	content, err := os.ReadFile(commitMsgFile) //nolint:gosec // Path comes from git hook
	if err != nil {
		return nil //nolint:nilerr // Hook must be silent on failure
	}

	message := string(content)

	// Check if our trailer is present (ParseCheckpoint validates format, so found==true means valid)
	if _, found := trailers.ParseCheckpoint(message); !found {
		// No trailer, nothing to do
		return nil
	}

	// One config read gives the comment prefix and whether commit.cleanup=strip
	// drops comment lines from every message, -m/-F ones included.
	configured, cleanup := gitCommentConfig(ctx)

	// Check if there's any user content (non-comment, non-trailer lines)
	if !hasUserContent(message, resolveCommentPrefix(configured, message), cleanup == cleanupStrip) {
		// No user content - strip the trailer so git aborts
		message = stripCheckpointTrailer(message)
		if err := os.WriteFile(commitMsgFile, []byte(message), 0o600); err != nil {
			return nil //nolint:nilerr // Hook must be silent on failure
		}
	}

	return nil
}

// PostRewrite is called by the git post-rewrite hook after amend/rebase
// operations. It keeps session linkage aligned with rewritten commit SHAs in
// the current worktree.
func (s *ManualCommitStrategy) PostRewrite(ctx context.Context, rewriteType string, r io.Reader) error {
	logCtx := logging.WithComponent(ctx, "checkpoint")
	if rewriteType != "amend" && rewriteType != "rebase" {
		logging.Debug(logCtx, "post-rewrite: unsupported rewrite type, skipping",
			slog.String("rewrite_type", rewriteType),
		)
		return nil
	}

	rewrites, err := parsePostRewritePairs(r)
	if err != nil {
		return err
	}
	if len(rewrites) == 0 {
		return nil
	}

	// Best-effort: a hook must not fail the user's amend or rebase.
	worktreePath, err := paths.WorktreeRoot(ctx)
	if err != nil {
		logging.Debug(logCtx, "post-rewrite: no worktree root, skipping",
			slog.String("error", err.Error()))
		return nil
	}

	sessions, err := s.findSessionsForWorktree(ctx, worktreePath)
	if err != nil {
		logging.Debug(logCtx, "post-rewrite: could not list sessions, skipping",
			slog.String("error", err.Error()))
		return nil
	}
	if len(sessions) == 0 {
		return nil
	}

	for _, sess := range sessions {
		sessionID := sess.SessionID
		mutErr := MutateSessionState(ctx, sessionID, func(state *SessionState) error {
			if !remapSessionForRewrite(state, rewrites) {
				return ErrMutationSkip
			}
			logging.Info(logCtx, "post-rewrite: remapped session linkage",
				slog.String("session_id", state.SessionID),
				slog.String("rewrite_type", rewriteType),
				slog.String("base_commit", truncateHash(state.BaseCommit)),
			)
			return nil
		})
		if mutErr != nil && !errors.Is(mutErr, ErrStateNotFound) {
			logging.Warn(logCtx, "post-rewrite: failed to remap session linkage",
				slog.String("session_id", sessionID),
				slog.String("error", mutErr.Error()),
			)
		}
	}

	return nil
}

func parsePostRewritePairs(r io.Reader) ([]rewritePair, error) {
	scanner := bufio.NewScanner(r)
	var pairs []rewritePair
	for scanner.Scan() {
		line := strings.TrimSpace(scanner.Text())
		if line == "" {
			continue
		}
		fields := strings.Fields(line)
		if len(fields) < 2 {
			return nil, fmt.Errorf("invalid post-rewrite mapping line: %q", line)
		}
		pairs = append(pairs, rewritePair{
			OldSHA: fields[0],
			NewSHA: fields[1],
		})
	}
	if err := scanner.Err(); err != nil {
		return nil, fmt.Errorf("scan post-rewrite input: %w", err)
	}
	return pairs, nil
}

// hasUserContent reports whether git will record anything in message besides
// Entire-Checkpoint trailers. With stripsComments (commit.cleanup=strip) git
// drops every line starting with commentPrefix from any message. Otherwise git
// does not tell commit-msg how the message was written, so the message has to
// say: an editor message ends with git's comment block or carries
// prepare-commit-msg's explanation, and git drops every line starting with
// commentPrefix plus the scissors line and everything below it; a -m/-F
// message has neither and git keeps its lines as written. A user who deletes
// both and types only commentPrefix lines is therefore read as having content.
func hasUserContent(message, commentPrefix string, stripsComments bool) bool {
	message = trailers.CutAtScissors(message, commentPrefix)
	if commentPrefix != "" && (stripsComments || strings.HasPrefix(lastNonBlankLine(message), commentPrefix) || strings.Contains(message, commentPrefix+trailerExplanation)) {
		message = trailers.StripEditorComments(message, commentPrefix)
	}
	trailerPrefix := trailers.CheckpointTrailerKey + ":"
	for _, line := range strings.Split(message, "\n") {
		if trimmed := strings.TrimSpace(line); trimmed != "" && !strings.HasPrefix(trimmed, trailerPrefix) {
			return true
		}
	}
	return false
}

// lastNonBlankLine returns the last line of message that is not blank, or ""
// when there is none.
func lastNonBlankLine(message string) string {
	lines := strings.Split(message, "\n")
	for i := len(lines) - 1; i >= 0; i-- {
		if strings.TrimSpace(lines[i]) != "" {
			return lines[i]
		}
	}
	return ""
}

// stripCheckpointTrailer removes the Entire-Checkpoint trailer line from the message.
func stripCheckpointTrailer(message string) string {
	trailerPrefix := trailers.CheckpointTrailerKey + ":"
	var result []string
	for _, line := range strings.Split(message, "\n") {
		if !strings.HasPrefix(strings.TrimSpace(line), trailerPrefix) {
			result = append(result, line)
		}
	}
	return strings.Join(result, "\n")
}

// isGitSequenceOperation checks if git is currently in the middle of a rebase,
// cherry-pick, or revert operation. During these operations, commits are being
// replayed and should not be linked to agent sessions.
//
// Detects:
//   - rebase: .git/rebase-merge/ or .git/rebase-apply/ directories
//   - cherry-pick: .git/CHERRY_PICK_HEAD file
//   - revert: .git/REVERT_HEAD file
func isGitSequenceOperation(ctx context.Context) bool {

	return false
}

// GitOperationInProgress names the git operation the worktree is in the middle
// of (rebase or am, cherry-pick, revert, merge, bisect), or returns "" when
// none is. A command about to move a branch must not do so mid-operation. A
// git dir that can't be read reports none, as isGitSequenceOperation does.
func GitOperationInProgress(ctx context.Context) string {
	gitDir, err := GetGitDir(ctx)
	if err != nil {
		return ""
	}
	// Per-worktree markers; see isGitSequenceOperation.
	root, err := gitdir.OpenAt(gitDir)
	if err != nil {
		return ""
	}
	for _, m := range []struct{ marker, op string }{
		{"rebase-merge", "a rebase"},
		{"rebase-apply", "a rebase or am"},
		{"CHERRY_PICK_HEAD", "a cherry-pick"},
		{"REVERT_HEAD", "a revert"},
		{"MERGE_HEAD", "a merge"},
		{"BISECT_LOG", "a bisect"},
	} {
		if _, err := root.Lstat(m.marker); err == nil {
			return m.op
		}
	}
	return ""
}

// PrepareCommitMsg is called by the git prepare-commit-msg hook.
// Adds an Entire-Checkpoint trailer to the commit message with a stable checkpoint ID.
// Only adds a trailer if there's actually new session content to condense.
// The actual condensation happens in PostCommit - if the user removes the trailer,
// the commit will not be linked to the session (useful for "manual" commits).
// For amended commits, preserves the existing checkpoint ID.
//
// The source parameter indicates how the commit was initiated:
//   - "" or "template": normal editor flow - adds trailer with explanatory comment
//   - "message": using -m or -F flag - prompts user interactively via /dev/tty
//   - "merge": skip trailer entirely (the merged commits keep their own)
//   - "squash": git's seeded squash message - inherits the squashed trailers, then matches as usual
//   - "commit": amend operation - preserves existing trailer or restores from LastCheckpointID
//

func (s *ManualCommitStrategy) PrepareCommitMsg(ctx context.Context, commitMsgFile string, source string) error {
	ctx = withCommitAncestry(ctx)
	logCtx := logging.WithComponent(ctx, "checkpoint")

	// Skip during rebase, cherry-pick, or revert operations
	// These are replaying existing commits and should not be linked to agent sessions
	if isGitSequenceOperation(ctx) {
		logging.Debug(logCtx, "prepare-commit-msg: skipped during git sequence operation",
			slog.String("strategy", "manual-commit"),
			slog.String("source", source),
		)
		return nil
	}

	// A trailer naming a checkpoint deleted from this clone goes first: kept,
	// post-commit would condense into the dead ID and re-create it.
	strippedDeleted := stripDeletedCheckpointTrailers(ctx, commitMsgFile)

	// Inherited trailers link the squashed commits' checkpoints; matching still
	// runs so work the session holds gets a checkpoint of its own.
	inherited := s.inheritSquashedCheckpointTrailers(ctx, commitMsgFile, source)
	recordInheritedTrailers(ctx, inherited)

	// A merge commit is skipped: the merged commits keep their own trailers.
	if source == "merge" {
		logging.Debug(logCtx, "prepare-commit-msg: skipped for source",
			slog.String("strategy", "manual-commit"),
			slog.String("source", source),
		)
		return nil
	}

	// Handle amend (source="commit") separately: preserve or restore trailer
	if source == "commit" {
		return s.prepareAmendCommitMsg(ctx, commitMsgFile, strippedDeleted)
	}

	repo, err := openRepositoryTimed(ctx)
	if err != nil {
		return nil
	}
	defer repo.Close()
	// Commits redone after a reset are links too: their trailers ride along.
	inherited, redone := s.withRedoneTrailers(ctx, repo, commitMsgFile, source, inherited)
	if redone.onlyRedone() {
		return nil // everything staged is work the inherited checkpoints hold
	}

	_, findSessionsSpan := perf.Start(ctx, "find_sessions_for_worktree")
	worktreePath, err := paths.WorktreeRoot(ctx)
	if err != nil {
		findSessionsSpan.RecordError(err)
		findSessionsSpan.End()
		return nil
	}

	// Union of worktree matching and identity matching (the committing
	// process's ancestry) — see findSessionsForCommitLinking; neither
	// suppresses the other. We match by worktree (not BaseCommit) because
	// the user may have made intermediate commits without entering new
	// prompts, causing HEAD to diverge
	sessions, err := s.findSessionsForCommitLinking(ctx, worktreePath)
	if err != nil || len(sessions) == 0 {
		findSessionsSpan.RecordError(err)
		findSessionsSpan.End()
		// No active sessions or error listing - silently skip (hooks must be resilient)
		logging.Debug(logCtx, "prepare-commit-msg: no active sessions",
			slog.String("strategy", "manual-commit"),
			slog.String("source", source),
		)
		return nil
	}
	findSessionsSpan.End()

	// Fast path: skip content detection for mid-turn agent commits. A session
	// whose agent provably did not make this commit is left to content
	// detection below.
	provenance := newCommitProvenance(ctx, sessions)
	if s.tryAgentCommitFastPath(ctx, commitMsgFile, provenance.withoutForeign(sessions), source, inherited) {
		return nil
	}

	// Check if any session has new content to condense
	_, filterSessionsSpan := perf.Start(ctx, "filter_sessions_with_content")
	sessionsWithContent := s.filterSessionsWithNewContent(ctx, repo, sessions, redone, provenance)
	filterSessionsSpan.End()

	if len(sessionsWithContent) == 0 {
		// No new content — no trailer needed
		logging.Debug(logCtx, "prepare-commit-msg: no content to link",
			slog.String("strategy", "manual-commit"),
			slog.String("source", source),
			slog.Int("sessions_found", len(sessions)),
		)
		return nil
	}

	// Read current commit message
	_, readCommitMessageSpan := perf.Start(ctx, "read_commit_message")
	content, err := os.ReadFile(commitMsgFile) //nolint:gosec // commitMsgFile is provided by git hook
	if err != nil {
		readCommitMessageSpan.RecordError(err)
		readCommitMessageSpan.End()
		return nil
	}

	message := string(content)
	commentPrefix := editorCommentPrefix(ctx, source, message)

	// A trailer prepare already stamped is kept (e.g. amend); inherited ones are links
	if existingCpID, found := stampedTrailer(ctx, message, commentPrefix, inherited); found {
		readCommitMessageSpan.End()
		// Trailer already exists (e.g., amend) - keep it
		logging.Debug(logCtx, "prepare-commit-msg: trailer already exists",
			slog.String("strategy", "manual-commit"),
			slog.String("source", source),
			slog.String("existing_checkpoint_id", existingCpID.String()),
		)
		return nil
	}
	readCommitMessageSpan.End()

	// Resolve the checkpoint ID and session metadata.
	_, resolveMetadataSpan := perf.Start(ctx, "resolve_session_metadata")
	checkpointID, err := checkpointIDForSessions(ctx, sessionsWithContent)
	if err != nil {
		resolveMetadataSpan.RecordError(err)
		resolveMetadataSpan.End()
		return fmt.Errorf("failed to generate checkpoint ID: %w", err)
	}

	agentType, displayPrompt, commitLinking := s.trailerPromptContext(ctx, sessionsWithContent)
	resolveMetadataSpan.End()

	// Add trailer differently based on commit source
	// NOTE: TTY confirmation (askConfirmTTY) is intentionally NOT wrapped in a span
	// because it blocks on user input and would skew timing.
	switch source {
	case commitSourceMessage:
		// Using -m or -F: behavior depends on TTY availability and commit_linking setting
		switch {
		case !interactive.CanPromptInteractively():
			// No TTY (agent subprocess, CI) — auto-link without prompting
			message = addCheckpointTrailer(message, checkpointID)
		case commitLinking == settings.CommitLinkingAlways:
			// User previously chose "always" — auto-link without prompting
			message = addCheckpointTrailer(message, checkpointID)
		default:
			// Human at terminal — prompt interactively
			header := "Entire: Active " + string(agentType) + " session detected"
			var details []string
			if displayPrompt != "" {
				details = append(details, "Last prompt: "+displayPrompt)
			}

			logging.Info(logCtx, CommitLinkingPromptLogMsg,
				slog.String("strategy", "manual-commit"),
				slog.String("source", source),
			)
			result := askConfirmTTY(header, details, "Link this commit to session context?", true)
			if result == ttyResultSkip {
				logging.Debug(logCtx, "prepare-commit-msg: user declined trailer",
					slog.String("strategy", "manual-commit"),
					slog.String("source", source),
				)
				return nil
			}
			if result == ttyResultLinkAlways {
				// Persist preference so future commits auto-link (non-fatal if it fails)
				if saveErr := saveCommitLinkingAlways(ctx); saveErr != nil {
					logging.Warn(logCtx, "prepare-commit-msg: failed to save commit_linking=always",
						slog.String("error", saveErr.Error()),
					)
				}
			}
			message = addCheckpointTrailer(message, checkpointID)
		}
	default:
		// Normal editor flow: add trailer with explanatory comment (will be stripped by git)
		message = addCheckpointTrailerWithComment(message, checkpointID, string(agentType), displayPrompt, commentPrefix)
	}

	logging.Info(logCtx, "prepare-commit-msg: trailer added",
		slog.String("strategy", "manual-commit"),
		slog.String("source", source),
		slog.String("checkpoint_id", checkpointID.String()),
	)

	// Write updated message back
	_, writeCommitMessageSpan := perf.Start(ctx, "write_commit_message")
	if err := os.WriteFile(commitMsgFile, []byte(message), 0o600); err != nil { //nolint:gosec // path from git hook arg
		writeCommitMessageSpan.RecordError(err)
		writeCommitMessageSpan.End()
		return nil
	}
	writeCommitMessageSpan.End()

	return nil
}

// trailerPromptContext returns what the trailer prompt shows and whether to
// ask: the first session's agent type and display-ready last prompt, and the
// commit_linking setting.
func (s *ManualCommitStrategy) trailerPromptContext(ctx context.Context, sessions []*SessionState) (types.AgentType, string, string) {
	var agentType types.AgentType
	var lastPrompt string
	if len(sessions) > 0 {
		firstSession := sessions[0]
		if firstSession.AgentType != "" {
			agentType = firstSession.AgentType
		}
		lastPrompt = s.getLastPrompt(ctx, firstSession)
	}

}

// handleAmendCommitMsg handles the prepare-commit-msg hook for amend operations
// (source="commit"). It preserves existing trailers or restores from LastCheckpointID.
func (s *ManualCommitStrategy) handleAmendCommitMsg(ctx context.Context, commitMsgFile string, strippedDeleted bool) error {
	logCtx := logging.WithComponent(ctx, "checkpoint")
	// Read current commit message
	content, err := os.ReadFile(commitMsgFile) //nolint:gosec // commitMsgFile is provided by git hook
	if err != nil {
		return nil
	}

	message := string(content)

	// If message already has a live trailer, keep it unchanged. A deleted ID
	// still mentioned somewhere (not as a whole trailer line, so not stripped)
	// does not count: preserving on it would keep the dead checkpoint linked.
	mentioned := trailers.ParseAllCheckpoints(message)
	if live := withoutDeletedCheckpoints(ctx, mentioned); len(live) > 0 {
		logging.Debug(logCtx, "prepare-commit-msg: amend preserves existing trailer",
			slog.String("strategy", "manual-commit"),
			slog.String("checkpoint_id", live[0].String()),
		)
		return nil
	} else if len(mentioned) > 0 {
		strippedDeleted = true
	}

	// No trailer in message — check if any session has LastCheckpointID to restore
	worktreePath, err := paths.WorktreeRoot(ctx)
	if err != nil {
		return nil
	}

	sessions, err := s.findSessionsForWorktree(ctx, worktreePath)
	if err != nil || len(sessions) == 0 {
		return nil
	}

	// For amend, HEAD^ is the commit being amended, and HEAD is where we are now.
	// We need to match sessions whose BaseCommit equals HEAD (the commit being amended
	// was created from this base). This prevents stale sessions from injecting
	// unrelated checkpoint IDs.
	repo, repoErr := OpenRepository(ctx)
	if repoErr != nil {
		return nil
	}
	defer repo.Close()
	head, headErr := repo.Head()
	if headErr != nil {
		return nil
	}
	currentHead := head.Hash().String()

	// Find first matching session with LastCheckpointID to restore.
	// LastCheckpointID is set after condensation completes.
	for _, state := range sessions {
		if state.BaseCommit != currentHead {
			continue
		}
		if state.LastCheckpointID.IsEmpty() {
			continue
		}
		// A delete lists the ID before clearing it from session state, so an
		// amend racing that window must not restore it.
		if len(withoutDeletedCheckpoints(ctx, []id.CheckpointID{state.LastCheckpointID})) == 0 {
			continue
		}
		cpID := state.LastCheckpointID
		source := "LastCheckpointID"

		// Restore the trailer
		message = addCheckpointTrailer(message, cpID)
		if writeErr := os.WriteFile(commitMsgFile, []byte(message), 0o600); writeErr != nil { //nolint:gosec // path from git hook arg
			return nil
		}

		logging.Info(logCtx, "prepare-commit-msg: restored trailer on amend",
			slog.String("strategy", "manual-commit"),
			slog.String("checkpoint_id", cpID.String()),
			slog.String("session_id", state.SessionID),
			slog.String("source", source),
		)
		return nil
	}

	if strippedDeleted {
		// The amended commit's checkpoint was deleted. Work a session still
		// holds gets a fresh checkpoint (see stampFreshCheckpointForAmend for
		// how this differs from an ordinary commit's linking).
		s.stampFreshCheckpointForAmend(ctx, repo, worktreePath, commitMsgFile)
		return nil
	}

	// No checkpoint ID found - leave message unchanged
	logging.Debug(logCtx, "prepare-commit-msg: amend with no checkpoint to restore",
		slog.String("strategy", "manual-commit"),
	)
	return nil
}

	}

	// Prepare prompt for display: collapse newlines/whitespace, then truncate (rune-safe)
	displayPrompt := stringutil.TruncateRunes(stringutil.CollapseWhitespace(lastPrompt), 80, "...")

	// Load commit_linking setting to decide whether to prompt
	commitLinking := settings.CommitLinkingPrompt // safe default
	if stngs, loadErr := settings.Load(ctx); loadErr == nil {
		commitLinking = stngs.GetCommitLinking()
	}
	return agentType, displayPrompt, commitLinking
}

// openRepositoryTimed opens the repository under an "open_repository" perf span.
func openRepositoryTimed(ctx context.Context) (*git.Repository, error) {
	_, span := perf.Start(ctx, "open_repository")
	defer span.End()
	repo, err := OpenRepository(ctx)
	if err != nil {
		span.RecordError(err)
		return nil, err
	}
	return repo, nil
}

// inheritSquashedCheckpointTrailers handles a commit made while `git merge
// --squash` is in progress (SQUASH_MSG present): the squashed commits'
// Entire-Checkpoint trailers are carried into the message when a staged path is
// one the recorded commits changed. `commit -m` reports source "message", not "squash", so this runs
// before the source switch — but only for those two sources: an amend must
// keep its own logic even when an abandoned squash left SQUASH_MSG behind.
// Returns the inherited IDs; nil when there are none or the message is
// unusable. Ordinary matching runs afterwards either way.
func (s *ManualCommitStrategy) inheritSquashedCheckpointTrailers(ctx context.Context, commitMsgFile, source string) []id.CheckpointID {
	if source != commitSourceMessage && source != "squash" {
		return nil
	}
	logCtx := logging.WithComponent(ctx, "checkpoint")
	gitDir, err := GetGitDir(ctx)
	if err != nil {
		return nil
	}
	// SQUASH_MSG lives in the PER-WORKTREE git dir, like the sequencer markers.
	// The root is the shared registry handle (gitdir.OpenAt): never close it.
	root, err := gitdir.OpenAt(gitDir)
	if err != nil {
		return nil
	}
	squashMsg, err := osroot.ReadFileNoFollow(root, "SQUASH_MSG")
	if err != nil {
		return nil // no squash in progress (or unreadable: fall through to normal matching)
	}

	inherited := withoutDeletedCheckpoints(ctx, trailers.ParseAllCheckpoints(string(squashMsg)))
	if len(inherited) == 0 {
		return nil
	}
	repo, err := OpenRepository(ctx)
	if err != nil {
		return nil
	}
	defer repo.Close()
	if !squashTouchesStagedPath(ctx, repo, squashMsg) {
		stripInheritedCheckpointTrailers(commitMsgFile, inherited)
		logging.Debug(logCtx, "prepare-commit-msg: ignored stale squash message whose commits changed none of the staged paths",
			slog.String("source", source),
			slog.Int("inherited", len(inherited)))
		return nil
	}
	content, err := os.ReadFile(commitMsgFile) //nolint:gosec // commitMsgFile is provided by git hook
	if err != nil {
		return nil // nothing inherited; let ordinary matching report its own failure
	}
	message := string(content)
	present := make(map[string]bool)
	for _, cpID := range trailers.ParseAllCheckpoints(message) {
		present[cpID.String()] = true
	}
	commentPrefix := editorCommentPrefix(ctx, source, message)
	added := 0
	for _, cpID := range inherited {
		if present[cpID.String()] {
			continue
		}
		message = addCheckpointTrailerAboveComments(message, cpID, commentPrefix)
		added++
	}
	if added == 0 {
		logging.Debug(logCtx, "prepare-commit-msg: squash in progress, message already carries the squashed trailers",
			slog.String("source", source),
			slog.Int("inherited", len(inherited)))
		return inherited
	}
	if err := os.WriteFile(commitMsgFile, []byte(message), 0o600); err != nil { //nolint:gosec // path from git hook arg
		return nil // nothing landed; hooks stay silent, ordinary matching may still try
	}
	logging.Info(logCtx, "prepare-commit-msg: inherited checkpoint trailers from the squashed commits",
		slog.String("strategy", "manual-commit"),
		slog.String("source", source),
		slog.Int("inherited", len(inherited)),
		slog.Int("added", added))
	return inherited
}

// squashTouchesStagedPath reports whether a staged path is one that a
// commit Git recorded in SQUASH_MSG changed. Git leaves SQUASH_MSG behind when a
// squash is abandoned, so the file alone is not proof that the current staged
// work belongs to those commits; matching paths rather than content keeps a
// squash whose files were touched up before committing.
func squashTouchesStagedPath(ctx context.Context, repo *git.Repository, squashMsg []byte) bool {
	files, err := getStagedFiles(ctx)
	if err != nil || len(files) == 0 {
		return false
	}
	staged := make(map[string]bool, len(files))
	for _, f := range files {
		staged[f] = true
	}
	for _, line := range strings.Split(string(squashMsg), "\n") {
		fields := strings.Fields(line)
		if len(fields) != 2 || fields[0] != "commit" || !plumbing.IsHash(fields[1]) {
			continue
		}
		commit, err := repo.CommitObject(plumbing.NewHash(fields[1]))
		if err != nil {
			continue
		}
		if commitChangesAnyPath(commit, staged) {
			return true
		}
	}
	return false
}

// commitChangesAnyPath reports whether c changed one of wanted relative to its
// first parent (or added it, for a root commit).
func commitChangesAnyPath(c *object.Commit, wanted map[string]bool) bool {
	tree, err := c.Tree()
	if err != nil {
		return false
	}
	var parentTree *object.Tree
	if parent, err := c.Parents().Next(); err == nil {
		if parentTree, err = parent.Tree(); err != nil {
			return false
		}
	}
	changes, err := object.DiffTree(parentTree, tree)
	if err != nil {
		return false
	}
	for _, change := range changes {
		if wanted[change.To.Name] || wanted[change.From.Name] {
			return true
		}
	}
	return false
}

func stripInheritedCheckpointTrailers(commitMsgFile string, inherited []id.CheckpointID) {
	content, err := os.ReadFile(commitMsgFile) //nolint:gosec // commitMsgFile is provided by git hook
	if err != nil {
		return
	}
	remove := make(map[string]bool, len(inherited))
	for _, cpID := range inherited {
		remove[trailers.CheckpointTrailerKey+": "+cpID.String()] = true
	}
	lines := strings.Split(string(content), "\n")
	kept := lines[:0]
	for _, line := range lines {
		if !remove[strings.TrimSpace(line)] {
			kept = append(kept, line)
		}
	}
	if err := os.WriteFile(commitMsgFile, []byte(strings.Join(kept, "\n")), 0o600); err != nil { //nolint:gosec // path from git hook arg
		return // hooks stay silent on failure
	}
}

// handleAmendCommitMsg handles the prepare-commit-msg hook for amend operations
// (source="commit"). It preserves existing trailers or restores from LastCheckpointID.
func (s *ManualCommitStrategy) handleAmendCommitMsg(ctx context.Context, commitMsgFile string, strippedDeleted bool) error {
	logCtx := logging.WithComponent(ctx, "checkpoint")
	// Read current commit message
	content, err := os.ReadFile(commitMsgFile) //nolint:gosec // commitMsgFile is provided by git hook
	if err != nil {
		return nil
	}

	message := string(content)

	// If the final trailer block already has a live trailer, keep it unchanged;
	// an ID elsewhere in the message is not this commit's link. A deleted ID
	// still mentioned somewhere (not as a whole trailer line, so not stripped)
	// does not count: preserving on it would keep the dead checkpoint linked.
	// Every final-block trailer is also a mention, so a message without one
	// skips reading the comment prefix from git config.
	if mentioned := trailers.ParseAllCheckpoints(message); len(mentioned) > 0 {
		if live := withoutDeletedCheckpoints(ctx, preparedFinalTrailers(message, gitCommentPrefix(ctx, message))); len(live) > 0 {
			logging.Debug(logCtx, "prepare-commit-msg: amend preserves existing trailer",
				slog.String("strategy", "manual-commit"),
				slog.String("checkpoint_id", live[0].String()),
			)
			return nil
		}
		if len(withoutDeletedCheckpoints(ctx, mentioned)) == 0 {
			strippedDeleted = true
		}
	}

	// No trailer in message — check if any session has LastCheckpointID to restore
	worktreePath, err := paths.WorktreeRoot(ctx)
	if err != nil {
		return nil
	}

	sessions, err := s.findSessionsForWorktree(ctx, worktreePath)
	if err != nil || len(sessions) == 0 {
		return nil
	}

	// For amend, HEAD^ is the commit being amended, and HEAD is where we are now.
	// We need to match sessions whose BaseCommit equals HEAD (the commit being amended
	// was created from this base). This prevents stale sessions from injecting
	// unrelated checkpoint IDs.
	repo, repoErr := OpenRepository(ctx)
	if repoErr != nil {
		return nil
	}
	defer repo.Close()
	head, headErr := repo.Head()
	if headErr != nil {
		return nil
	}
	currentHead := head.Hash().String()

	// Find first matching session with LastCheckpointID to restore.
	// LastCheckpointID is set after condensation completes.
	for _, state := range sessions {
		if state.BaseCommit != currentHead {
			continue
		}
		if state.LastCheckpointID.IsEmpty() {
			continue
		}
		// A delete lists the ID before clearing it from session state, so an
		// amend racing that window must not restore it.
		if len(withoutDeletedCheckpoints(ctx, []id.CheckpointID{state.LastCheckpointID})) == 0 {
			continue
		}
		cpID := state.LastCheckpointID
		source := "LastCheckpointID"

		// Restore the trailer
		message = addCheckpointTrailerAboveComments(message, cpID, gitCommentPrefix(ctx, message))
		if writeErr := os.WriteFile(commitMsgFile, []byte(message), 0o600); writeErr != nil { //nolint:gosec // path from git hook arg
			return nil
		}

		logging.Info(logCtx, "prepare-commit-msg: restored trailer on amend",
			slog.String("strategy", "manual-commit"),
			slog.String("checkpoint_id", cpID.String()),
			slog.String("session_id", state.SessionID),
			slog.String("source", source),
		)
		return nil
	}

	if strippedDeleted {
		// The amended commit's checkpoint was deleted. Work a session still
		// holds gets a fresh checkpoint (see stampFreshCheckpointForAmend for
		// how this differs from an ordinary commit's linking).
		s.stampFreshCheckpointForAmend(ctx, repo, worktreePath, commitMsgFile)
		return nil
	}

	// No checkpoint ID found - leave message unchanged
	logging.Debug(logCtx, "prepare-commit-msg: amend with no checkpoint to restore",
		slog.String("strategy", "manual-commit"),
	)
	return nil
}

// stampFreshCheckpointForAmend links an amend whose deleted checkpoint trailer
// was removed to a new checkpoint when a session has new content for it. With
// nothing new, the amend simply carries no trailer.
//
// It runs only the core of ordinary linking: find the linkable sessions, keep
// those with new content, pick their checkpoint ID, and append a plain
// trailer. It deliberately skips the rest of PrepareCommitMsg's path: no
// mid-turn agent fast path, no TTY link prompt, and no explanatory editor
// comment beside the trailer. An amend's
// source is always "commit", and the old trailer it replaces carried no
// comment either.
func (s *ManualCommitStrategy) stampFreshCheckpointForAmend(ctx context.Context, repo *git.Repository, worktreePath, commitMsgFile string) {
	logCtx := logging.WithComponent(ctx, "checkpoint")
	sessions, err := s.findSessionsForCommitLinking(ctx, worktreePath)
	if err != nil || len(sessions) == 0 {
		return
	}
	withContent := s.filterSessionsWithNewContent(ctx, repo, sessions, redo{}, newCommitProvenance(ctx, sessions))
	if len(withContent) == 0 {
		return
	}
	cpID, err := checkpointIDForSessions(ctx, withContent)
	if err != nil {
		return
	}
	content, err := os.ReadFile(commitMsgFile) //nolint:gosec // commitMsgFile is provided by git hook
	if err != nil {
		return
	}
	message := string(content)
	message = addCheckpointTrailerAboveComments(message, cpID, gitCommentPrefix(ctx, message))
	if err := os.WriteFile(commitMsgFile, []byte(message), 0o600); err != nil { //nolint:gosec // path from git hook arg
		return
	}
	logging.Info(logCtx, "prepare-commit-msg: amend of a deleted checkpoint linked to a new one",
		slog.String("strategy", "manual-commit"),
		slog.String("checkpoint_id", cpID.String()),
	)
}

// withoutDeletedCheckpoints drops IDs deleted from this clone, so inheriting
// trailers (squash, redo) cannot put back one stripDeletedCheckpointTrailers
// removed. An unreadable list filters nothing: hooks fail open.
func withoutDeletedCheckpoints(ctx context.Context, ids []id.CheckpointID) []id.CheckpointID {
	if len(ids) == 0 {
		return ids
	}
	deleted, err := checkpoint.LoadDeletedCheckpoints(ctx)
	if err != nil || len(deleted) == 0 {
		return ids
	}
	kept := make([]id.CheckpointID, 0, len(ids))
	for _, cpID := range ids {
		if !deleted.Contains(cpID) {
			kept = append(kept, cpID)
		}
	}
	return kept
}

// stripDeletedCheckpointTrailers removes Entire-Checkpoint trailers naming
// checkpoints deleted from this clone, reporting whether the message file was
// actually rewritten. Every whole (possibly indented) trailer line after the
// subject and above any scissors line is considered, by the same matcher that
// decides what to remove (see trailers.RemoveCheckpointTrailers). A list that
// cannot be read strips nothing: hooks fail open.
func stripDeletedCheckpointTrailers(ctx context.Context, commitMsgFile string) bool {
	logCtx := logging.WithComponent(ctx, "checkpoint")
	deleted, err := checkpoint.LoadDeletedCheckpoints(ctx)
	if err != nil {
		logging.Debug(logCtx, "prepare-commit-msg: deleted checkpoints list unavailable",
			slog.String("error", err.Error()))
		return false
	}
	if len(deleted) == 0 {
		return false
	}

}

// attachLinkMode is how attach links a checkpoint to its target commit. It
// follows from two facts about the commit — does it already have a checkpoint,
// and is it pushed — never from a flag or from whether it is HEAD.
type attachLinkMode int

const (
	// attachJoinExisting: the commit's final trailer block already carries an
	// Entire-Checkpoint trailer; the session joins that checkpoint and history
	// is unchanged.
	attachJoinExisting attachLinkMode = iota
	// attachAddTrailer: no remote branch holds the commit. The trailer is
	// added, rewriting the commit and any after it: nobody else has them, and
	// a trailer survives a later rebase, where a recorded link wouldn't.
	attachAddTrailer
	// attachRecordLink: a remote branch already holds the commit, so rewriting
	// it would mean a force-push. The link is recorded in the checkpoint
	// (LinkedCommits) and the commit is left alone.
	attachRecordLink
)

// attachLinkPlan is the commit an attach links to and how.
type attachLinkPlan struct {
	target *object.Commit
	mode   attachLinkMode
	// holder is a remote whose branches hold target, empty when none does (or,
	// when joining, none could be reached).
	holder string
	// remote is where the checkpoint is pushed now: holder, or the branch's own
	// remote when holder is an unrelated one. Empty when holder is.
	remote string
	// rewrite is target and the commits after it up to HEAD, oldest first
	// (attachAddTrailer only).
	rewrite []*object.Commit
	// checkedRemotes are the remotes asked whether they hold target.
	checkedRemotes []string
}

// planAttachLink resolves the target (HEAD unless --commit names another) and
// decides how to link it.
func planAttachLink(ctx context.Context, repo *git.Repository, headCommit *object.Commit, opts attachOptions) (attachLinkPlan, error) {
	target := headCommit
	if opts.Commit != "" {
		var err error
		if target, err = resolveAttachCommit(repo, opts.Commit); err != nil {
			return attachLinkPlan{}, err
		}
	}
	remotes := attachRemotesToCheck(ctx)
	if len(strategy.FinalCheckpointTrailers(ctx, target.Message)) > 0 {
		// Joining changes no history, so whether the commit is pushed only
		// decides when the checkpoint goes out: now if it is, since there may be
		// no later push of it, else with the next git push. A remote that can't
		// be reached leaves it for that push.
		holder, pushTo, _, err := remoteHoldingPushedCommit(ctx, target, remotes)
		if err != nil {
			return attachLinkPlan{}, err
		}
		return attachLinkPlan{target: target, mode: attachJoinExisting, remote: pushTo, holder: holder, checkedRemotes: remotes}, nil
	}
	holder, pushTo, unreachable, err := remoteHoldingPushedCommit(ctx, target, remotes)
	if err != nil {
		return attachLinkPlan{}, err
	}
	if holder != "" {
		return attachLinkPlan{target: target, mode: attachRecordLink, remote: pushTo, holder: holder, checkedRemotes: remotes}, nil
	}
	if len(unreachable) > 0 {
		// Absence from a remote we couldn't reach proves nothing; rewriting a
		// commit someone already pushed is what this rule exists to prevent.
		return attachLinkPlan{}, fmt.Errorf("couldn't confirm that commit %s isn't already pushed (could not reach %s), so it won't be rewritten; retry when the remote is reachable",
			target.Hash.String()[:12], strings.Join(unreachable, ", "))
	}
	chain, err := attachRewriteChain(ctx, repo, target, headCommit)
	if err != nil {
		return attachLinkPlan{}, err
	}
	return attachLinkPlan{target: target, mode: attachAddTrailer, rewrite: chain, checkedRemotes: remotes}, nil
}

// remoteHoldingPushedCommit returns a remote whose branches contain target
// (holder) and the remote to push its checkpoint to, both "" when none does,
// plus the remotes it could not reach. Remote-tracking refs
// can be stale — someone may have pushed this commit from another clone — and
// rewriting a shared commit is what attach must avoid, so remotes are
// refreshed first, then asked directly: tracking refs may not cover every
// branch (single-branch clones, narrowed refspecs).
func remoteHoldingPushedCommit(ctx context.Context, target *object.Commit, remotes []string) (holder, pushTo string, unreachable []string, err error) {
	fetchRemotesForAttach(ctx, remotes)
	if holder, pushTo, err = remoteHoldingCommit(ctx, target, remotes); err != nil || holder != "" {
		return holder, pushTo, nil, err
	}
	holder, unreachable = remoteContainingCommit(ctx, target, remotes)
	return holder, holder, unreachable, nil
}

// checkpointLinkedTo finds the most recent checkpoint whose recorded links
// name target, reading remote-discovered stubs for theirs. A listing failure
// finds none.
func checkpointLinkedTo(ctx context.Context, store cpkg.PersistentStore, target *object.Commit) (id.CheckpointID, bool) {
	infos, err := store.List(ctx)
	if err != nil {
		logging.Debug(ctx, "attach: listing checkpoints for a recorded link failed", slog.String("error", err.Error()))
		return id.EmptyCheckpointID, false
	}
	linked := cpkg.CheckpointsLinkedToWithStubs(ctx, store, infos, target.Hash.String(), target.Committer.When)
	if len(linked) == 0 {
		return id.EmptyCheckpointID, false
	}
	return linked[0], true
}

