	block := "# Please enter the commit message for your changes. Lines starting\n# with '#' will be ignored, and an empty message aborts the commit.\n#\n# On branch main\n"

	// 1. -m "fix" -e: source message, trailer appended after git's block, user clears "fix".
	prepared := addCheckpointTrailer("fix\n\n"+block, cp)
	fmt.Printf("1 prepared=%q\n", prepared)
	cleared := prepared[len("fix\n"):]
	fmt.Printf("1 hasUserContent(cleared)=%v (want false)\n", hasUserContent(cleared, "#", false))

	// 2. scissors cleanup, subject "#42 fix login"
	sc := "\n# ------------------------ >8 ------------------------\n# Do not modify or remove the line above.\n# Everything below it will be ignored.\n# On branch main\n"
	p2 := addCheckpointTrailerWithComment(sc, cp, "Claude Code", "", "#")
	e2 := "#42 fix login" + p2
	fmt.Printf("2 edited=%q\n", e2)
	fmt.Printf("2 hasUserContent=%v (git keeps the subject under scissors)\n", hasUserContent(e2, "#", false))

	// 3. template with comment prompts
	tmpl := "\n# Title: summary\n\n# Body: explain why\n\n" + block
	p3 := addCheckpointTrailerWithComment(tmpl, cp, "Claude Code", "", "#")
	fmt.Printf("3 prepared=%q\n", p3)
	// user types subject on line 0 and body under "# Body:"
	e3 := "Fix login" + p3
	e3 = replaceOnce(e3, "# Body: explain why\n", "# Body: explain why\nBecause the session expired.\n")
	rec := trailers.StripEditorComments(e3, "#")
	fmt.Printf("3 recorded(before stripspace)=%q\n", rec)
	fmt.Printf("3 final=%v\n", trailers.ParseAllCheckpointsFromFinalTrailerBlock(rec, ""))

	// 4. -s signoff, untouched template
	p4 := addCheckpointTrailerWithComment("\n\nSigned-off-by: Me <me@x>\n\n"+block, cp, "Claude Code", "", "#")
	fmt.Printf("4 prepared=%q hasUserContent=%v\n", p4, hasUserContent(p4, "#", false))

	// 5. auto prefix fallback
	fmt.Printf("5 auto(-m '#42 fix' + trailer)=%q\n", trailers.AutoCommentPrefix("#42 fix\n\nEntire-Checkpoint: a1b2c3d4e5f6\n"))
	fmt.Printf("5 auto(template '# Release notes' no block)=%q\n", trailers.AutoCommentPrefix("# Release notes\n"))
}

func replaceOnce(s, old, new string) string {
	for i := 0; i+len(old) <= len(s); i++ {
		if s[i:i+len(old)] == old {
			return s[:i] + new + s[i+len(old):]
		}
	}
	return s
}
